def count_Rectangles(radius):
    """Count rectangles with integer sides that fit inside a circle of radius r.

    A rectangle with sides length and width fits iff its diagonal
    satisfies length**2 + width**2 <= (2 * radius)**2.
    """
    if radius is None:
        return 0
    try:
        if radius <= 0:
            return 0
    except TypeError:
        return 0
    diameter = 2 * radius
    max_side = int(diameter + 1e-9)
    limit = diameter * diameter
    count = 0
    for length in range(1, max_side + 1):
        for width in range(1, max_side + 1):
            if length * length + width * width <= limit + 1e-9:
                count += 1
    return count
